        g_d3d_device->vtbl->SetTextureStageState(g_d3d_device, 0, 4, 4);
        g_d3d_device->vtbl->SetTextureStageState(g_d3d_device, 0, 5, 2);
        g_d3d_device->vtbl->SetTextureStageState(g_d3d_device, 0, 6, 0);
